catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // Enforce an enterprise minimum length of 15 characters for business justification notes
    var minLength = 15;

    if (newValue.length < minLength) {
        // Clear a previous message if it exists
        g_form.hideFieldMsg('facilities_additional_notes');

        // Inject a live, user-friendly warning right under the specific field input box
        g_form.showFieldMsg('facilities_additional_notes', 'Please provide a more detailed justification (Minimum ' + minLength + ' characters). Current length: ' + newValue.length, 'error');
    } else {
        // If they fixed it and crossed the threshold, clear the error box cleanly
        g_form.hideFieldMsg('facilities_additional_notes');
    }
}
